package net.civeira.phylax.features.notification.message.domain.valueobject;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.notification.message.domain.Message;

@RequiredArgsConstructor
public class TargetValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<TargetVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getTarget() {
    return value.map(TargetVO::getTarget);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<TargetVO> getTargetValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public TargetVO readTarget(final Optional<Message> original, final ConstraintFailList fails) {
    TargetVO result = value.orElse(original.map(Message::getTargetValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "target", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param target
   * @return
   */
  public T target(TargetVO target) {
    this.value = Optional.of(target);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param target
   * @return
   */
  public T target(Optional<TargetVO> target) {
    this.value = target;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param target
   * @return
   */
  public T target(String target) {
    this.value = Optional.of(TargetVO.from(target));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetTarget() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetTargetIfMatches(final String field) {
    if ("target".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
